I would like to clarify the behavior once either of these amendments are adopted:

1. Suppose an Issuer (I) locks the MPToken ledger-entry of a Holder (H).
2. Issuer (I) deletes their MPTokenIssuance ledger-entry.
3. Holder (H) cannot delete their dangling MPToken entry
4. Holder (H) also cannot delete their account because MPToken is an AccountDeletion-Blocker.

I could not find this caveat mentioned in the documentation of `MPToken` ledger-object (or) the `MPTokenAuthorize`. I believe this is useful knowledge for MPToken users.


Here is the patch file that demonstrates this behavior: 
```
diff --git a/src/test/app/MPToken_test.cpp b/src/test/app/MPToken_test.cpp
index 97b9b392a0..09a43c1700 100644
--- a/src/test/app/MPToken_test.cpp
+++ b/src/test/app/MPToken_test.cpp
@@ -3,6 +3,7 @@
 #include <test/jtx/Account.h>
 #include <test/jtx/Env.h>
 #include <test/jtx/TestHelpers.h>
+#include <test/jtx/acctdelete.h>
 #include <test/jtx/amount.h>
 #include <test/jtx/balance.h>  // IWYU pragma: keep
 #include <test/jtx/check.h>
@@ -880,6 +881,73 @@ class MPToken_test : public beast::unit_test::Suite
         }
     }

+    void
+    testLockedMPTokenDestroyedIssuance(FeatureBitset features)
+    {
+        testcase("Locked MPToken with destroyed issuance");
+
+        using namespace test::jtx;
+        Account const alice("alice");  // issuer
+        Account const bob("bob");      // holder
+
+        Env env{*this, features};
+        MPTTester mptAlice(env, alice, {.holders = {bob}});
+
+        // create a mptokenissuance with locking
+        mptAlice.create({.ownerCount = 1, .holderCount = 0, .flags = tfMPTCanLock});
+
+        // bob creates an empty MPToken
+        mptAlice.authorize({.account = bob, .holderCount = 1});
+
+        // alice locks bob's mptoken individually
+        mptAlice.set({.account = alice, .holder = bob, .flags = tfMPTLock});
+
+        // alice destroys her issuance. This succeeds: MPTokenIssuanceDestroy
+        // only requires that the issuance has no outstanding balance; it does
+        // not require that all holder MPTokens have been deleted first.
+        mptAlice.destroy({.ownerCount = 0});
+
+        auto const acctDelFee{drops(env.current()->fees().increment)};
+
+        if (features[featureSingleAssetVault] || features[fixCleanup3_4_0])
+        {
+            // bob cannot delete his locked MPToken, even though the issuance
+            // no longer exists ...
+            mptAlice.authorize(
+                {.account = bob, .flags = tfMPTUnauthorize, .err = tecNO_PERMISSION});
+
+            // ... and the lock can never be cleared, because unlocking
+            // requires the (destroyed) issuance
+            mptAlice.set(
+                {.account = alice,
+                 .holder = bob,
+                 .flags = tfMPTUnlock,
+                 .err = tecOBJECT_NOT_FOUND});
+
+            // the dangling locked MPToken survives ...
+            BEAST_EXPECT(
+                env.current()->exists(keylet::mptoken(mptAlice.issuanceID(), bob.id())));
+            BEAST_EXPECT(ownerCount(env, bob) == 1);
+
+            // ... so bob's account can never be deleted
+            incLgrSeqForAccDel(env, bob);
+            env(acctdelete(bob, alice), Fee(acctDelFee), Ter(tecHAS_OBLIGATIONS));
+            env.close();
+        }
+        else
+        {
+            // pre-amendment: bob deletes the dangling locked MPToken ...
+            mptAlice.authorize(
+                {.account = bob, .holderCount = 0, .flags = tfMPTUnauthorize});
+            BEAST_EXPECT(ownerCount(env, bob) == 0);
+
+            // ... and can then delete his account
+            incLgrSeqForAccDel(env, bob);
+            env(acctdelete(bob, alice), Fee(acctDelFee));
+            env.close();
+        }
+    }
